class Ledger(StructuredNode):
    """Model Ledger (table ledgers)."""

    year = IntegerProperty(index=True, required=True)
    number = IntegerProperty(index=True, required=True)
    memo = StringProperty(index=True, fulltext_index=FulltextIndex())
    code = StringProperty(unique_index=True, required=True)
    owner_id = IntegerProperty()
    parent_id = IntegerProperty()
    parent = RelationshipTo("Ledger", "PARENT", cardinality=ZeroOrOne)
    children = RelationshipFrom("Ledger", "PARENT", cardinality=ZeroOrMore)
    line_items = RelationshipFrom("LineItem", "LEDGER", cardinality=ZeroOrMore)


class LineItem(StructuredNode):
    """Model LineItem (table line_items)."""

    id_ = IntegerProperty(unique_index=True, required=True, db_property="id")
    ledger_year = IntegerProperty(required=True)
    ledger_number = IntegerProperty(required=True)
    ledger = RelationshipTo("Ledger", "LEDGER", cardinality=One)


